        radial-gradient(circle at top right, #e9dcc8 0, transparent 28%),
        var(--color-bg);
      color: var(--color-text);
    }

    a {
      color: var(--color-link);
      text-decoration-thickness: 0.1em;
      text-underline-offset: 0.18em;
    }

    a:hover {
      color: var(--color-accent-strong);
    }

    img {
      display: block;
      max-width: 100%;
    }

    button,
    input,
    a {
      font: inherit;
    }

    button {
      border: 0;
      cursor: pointer;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      z-index: 20;
      padding: 0.85rem 1rem;
      border-radius: 999px;
      background: var(--color-surface);
      color: var(--color-text);
      box-shadow: var(--shadow);
      transform: translateY(-160%);
      transition: transform 160ms ease;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid var(--color-focus);
      outline-offset: 2px;
    }

    .shell {
      width: min(calc(100% - 2rem), var(--page-max));
      margin: 0 auto;
    }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 10;
      backdrop-filter: blur(18px);
      background: color-mix(in srgb, var(--color-bg) 78%, transparent);
      border-bottom: 1px solid var(--color-border);
    }

    .site-header__inner {
      display: flex;
      align-items: center;
      gap: 1rem;
      justify-content: space-between;
      padding: 1rem 0;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.75rem;
      color: var(--color-text);
      text-decoration: none;
      font-weight: 800;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .brand-mark {
      inline-size: 2.25rem;
      block-size: 2.25rem;
      border-radius: 999px;
      background:
        linear-gradient(145deg, #f7e0c2, #d49b62 48%, #8c4e22);
      box-shadow: inset 0 0 0 1px #d8b28a;
    }

    .primary-nav ul,
    .footer-nav ul {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem 1rem;
      list-style: none;
      padding: 0;
      margin: 0;
    }

    .brand,
    .primary-nav a,
    .footer-nav a,
    .story-card a,
    .btn,
    .card__button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      padding: 0.45rem 0.7rem;
      border-radius: 999px;
      color: var(--color-text);
      text-decoration: none;
      transition: background-color 160ms ease, color 160ms ease;
      outline: 2px solid transparent;
      outline-offset: 3px;
    }

    .primary-nav a:hover,
    .footer-nav a:hover {
      background: var(--color-surface);
      color: var(--color-accent-strong);
    }

    .utility {
      display: inline-flex;
      align-items: center;
      gap: 0.75rem;
    }

    .bag-pill {
      display: inline-flex;
      align-items: center;
      gap: 0.45rem;
      padding: 0.65rem 0.9rem;
      border-radius: 999px;
      background: var(--color-surface);
      border: 1px solid var(--color-border);
      color: var(--color-text);
      box-shadow: 0 10px 20px -18px #5d4f41;
      white-space: nowrap;
    }

    .bag-pill__count {
      min-width: 1.65rem;
      padding: 0.1rem 0.45rem;
      border-radius: 999px;
      background: var(--color-accent);
      color: #fff;
      text-align: center;
      font-size: 0.9rem;
      font-weight: 700;
    }

    main:focus {
      outline: 3px solid var(--color-focus);
      outline-offset: 0.5rem;
    }

    .hero {
      display: grid;
      grid-template-columns: 1.15fr 0.85fr;
      gap: 1.5rem;
      align-items: stretch;
      padding: 2rem 0 1rem;
    }

    .hero__content,
    .hero__visual,
    .section-card,
    .feature-card,
    .deal-card,
    .story-card {
      border: 1px solid var(--color-border);
      background: var(--color-surface);
      box-shadow: var(--shadow);
    }

    .hero__content {
      border-radius: var(--radius-xl);
      padding: clamp(1.5rem, 3vw, 3rem);
      display: grid;
      gap: 1.25rem;
      align-content: start;
    }

    .eyebrow {
      display: inline-flex;
      width: fit-content;
      align-items: center;
      gap: 0.5rem;
      padding: 0.35rem 0.75rem;
      border-radius: 999px;
      background: var(--color-surface-2);
      color: var(--color-accent-strong);
      font-size: 0.88rem;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    h1,
    h2,
    h3,
    p {
      margin: 0;
    }

    h1 {
      font-size: clamp(2.6rem, 6vw, 5.5rem);
      line-height: 0.98;
      letter-spacing: -0.05em;
      max-width: 11ch;
    }

    .lede {
      max-width: 58ch;
      color: var(--color-muted-text);
      font-size: 1.08rem;
    }

    .hero__actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.8rem;
      align-items: center;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.5rem;
      min-height: 3rem;
      padding: 0.85rem 1.1rem;
      border-radius: 999px;
      text-decoration: none;
      font-weight: 700;
      transition: transform 160ms ease, background-color 160ms ease, color 160ms ease, border-color 160ms ease;
      outline: 2px solid transparent;
      outline-offset: 3px;
    }

    .btn:focus-visible,
    .brand:focus-visible,
    .card__button:focus-visible,
    .story-card a:focus-visible,
    .primary-nav a:focus-visible,
    .footer-nav a:focus-visible {
      outline-color: var(--color-focus);
      box-shadow: 0 0 0 4px #dbe7ff;
    }

    .btn--primary,
    .card__button {
      background: var(--color-accent);
      color: #fff;
      border: 1px solid var(--color-accent-strong);
    }

    .btn--secondary {
      background: var(--color-surface);
      color: var(--color-text);
      border: 1px solid var(--color-border);
    }

    .hero__stats {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.75rem;
      margin-top: 0.25rem;
    }

    .stat {
      padding: 1rem;
      border-radius: var(--radius-md);
      background: var(--color-surface-2);
      border: 1px solid var(--color-border);
    }

    .stat strong {
      display: block;
      font-size: 1.1rem;
      margin-bottom: 0.2rem;
    }

    .hero__visual {
      border-radius: var(--radius-xl);
      overflow: hidden;
      display: grid;
      grid-template-rows: auto 1fr;
    }

    .hero__art {
      position: relative;
      min-height: 18rem;
      background:
        radial-gradient(circle at 25% 30%, #fff8ee 0, #f0dcc1 24%, transparent 25%),
        radial-gradient(circle at 78% 18%, #f7d8b5 0, transparent 20%),
        linear-gradient(150deg, #c9864e, #f0c59a 44%, #f7efe4);
    }

    .hero__art::before,
    .hero__art::after {
      content: "";
      position: absolute;
      border-radius: 28px;
      box-shadow: inset 0 0 0 1px #e0b18c;
    }

    .hero__art::before {
      inset: 14% 10% 20% 42%;
      background: linear-gradient(180deg, #fffaf4 0, #ead8c1 100%);
      transform: rotate(8deg);
    }

    .hero__art::after {
      inset: 20% 52% 12% 12%;
      background:
        linear-gradient(180deg, #7a4525 0, #c08455 100%);
      transform: rotate(-10deg);
    }

    .hero__panel {
      display: grid;
      gap: 1rem;
      padding: 1.25rem;
      background: var(--color-surface);
    }

    .hero__panel h2 {
      font-size: 1.1rem;
    }

    .hero__panel p {
      color: var(--color-muted-text);
    }

    .hero__panel-list {
      display: grid;
      gap: 0.65rem;
      list-style: none;
      padding: 0;
      margin: 0;
    }

    .hero__panel-list li {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      padding: 0.75rem 0.9rem;
      border-radius: var(--radius-sm);
      background: var(--color-surface);
      border: 1px solid var(--color-border);
    }

    .dot {
      inline-size: 0.7rem;
      block-size: 0.7rem;
      border-radius: 999px;
      background: var(--color-success);
      box-shadow: 0 0 0 4px #dff2e8;
      flex: 0 0 auto;
    }

    .section {
      padding: 1.25rem 0 0;
    }

    .section__header {
      display: flex;
      gap: 1rem;
      align-items: end;
      justify-content: space-between;
      margin-bottom: 1rem;
    }

    .section__header p {
      max-width: 52ch;
      color: var(--color-muted-text);
    }

    .section__link {
      color: var(--color-accent-strong);
      font-weight: 700;
      text-decoration: none;
      white-space: nowrap;
    }

    .grid {
      display: grid;
      gap: 1rem;
    }

    .grid--products {
      grid-template-columns: repeat(4, minmax(0, 1fr));
    }

    .grid--deals,
    .grid--stories {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .feature-card,
    .deal-card,
    .story-card {
      border-radius: var(--radius-lg);
      overflow: hidden;
    }

    .feature-card__media {
      min-height: 11rem;
      padding: 1rem;
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      gap: 1rem;
      color: #fff;
    }

    .feature-card__tag {
      display: inline-flex;
      align-items: center;
      padding: 0.35rem 0.65rem;
      border-radius: 999px;
      background: #ffffff;
      color: var(--color-text);
      font-size: 0.78rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.05em;
    }

    .feature-card__shine {
      inline-size: 4rem;
      block-size: 4rem;
      border-radius: 20px;
      background: linear-gradient(140deg, #ffffff, rgba(255, 255, 255, 0));
      opacity: 0.85;
    }

    .feature-card__body,
    .deal-card__body,
    .story-card__body {
      display: grid;
      gap: 0.75rem;
      padding: 1.1rem;
    }

    .feature-card__title {
      font-size: 1.08rem;
    }

    .feature-card__meta,
    .deal-card__meta,
    .story-card__meta {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      align-items: center;
      color: var(--color-muted-text);
      font-size: 0.94rem;
    }

    .price {
      font-weight: 800;
      color: var(--color-text);
    }

    .card__button {
      width: 100%;
      padding-inline: 1rem;
      border-radius: 999px;
    }

    .deal-card {
      display: grid;
      gap: 0;
      background: linear-gradient(180deg, #fffaf4 0, #f3eadf 100%);
    }

    .deal-card__flag {
      display: inline-flex;
      width: fit-content;
      align-items: center;
      padding: 0.35rem 0.65rem;
      border-radius: 999px;
      background: #fff3d8;
      color: #7a4b08;
      font-weight: 800;
      letter-spacing: 0.03em;
      text-transform: uppercase;
      font-size: 0.78rem;
    }

    .deal-card__value {
      font-size: clamp(2rem, 4vw, 3rem);
      line-height: 0.95;
      letter-spacing: -0.04em;
    }

    .story-card h3 {
      font-size: 1.1rem;
    }

    .story-card p {
      color: var(--color-muted-text);
    }

    .story-card a {
      width: fit-content;
      font-weight: 700;
    }

    .site-footer {
      margin-top: 2rem;
      padding: 1.5rem 0 2rem;
      border-top: 1px solid var(--color-border);
    }

    .site-footer__inner {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
      align-items: center;
      justify-content: space-between;
    }

    .site-footer p {
      color: var(--color-muted-text);
    }

    .status {
      position: absolute;
      inline-size: 1px;
      block-size: 1px;
      padding: 0;
      overflow: hidden;
      clip: rect(0 0 0 0);
      clip-path: inset(50%);
      white-space: nowrap;
      border: 0;
    }

    @media (prefers-reduced-motion: no-preference) {
      .btn:hover,
      .card__button:hover,
      .story-card a:hover {
        transform: translateY(-1px);
      }

      .primary-nav a,
      .footer-nav a,
      .btn,
      .card__button,
      .story-card a {
        transition: transform 160ms ease, background-color 160ms ease, color 160ms ease, border-color 160ms ease, box-shadow 160ms ease;
      }

      html {
        scroll-behavior: smooth;
      }
    }

    @media (max-width: 980px) {
      .hero,
      .grid--products,
      .grid--deals,
      .grid--stories {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .site-header__inner,
      .section__header,
      .site-footer__inner {
        align-items: start;
        flex-direction: column;
      }
    }

    @media (max-width: 640px) {
      .shell {
        width: min(calc(100% - 1.1rem), var(--page-max));
      }

      .site-header__inner {
        gap: 0.75rem;
      }

      .hero,
      .grid--products,
      .grid--deals,
      .grid--stories,
      .hero__stats {
        grid-template-columns: 1fr;
      }

      .hero__content,
      .hero__visual {
        border-radius: var(--radius-lg);
      }

      h1 {
        max-width: 12ch;
      }
    }

    @media (forced-colors: active) {
      :root {
        --color-bg: Canvas;
        --color-surface: Canvas;
        --color-surface-2: Canvas;
        --color-text: CanvasText;
        --color-muted-text: CanvasText;
        --color-link: LinkText;
        --color-border: ButtonBorder;
        --color-focus: Highlight;
        --color-accent: ButtonFace;
        --color-accent-strong: ButtonText;
        --color-success: CanvasText;
      }

      .site-header,
      .hero__content,
      .hero__visual,
      .feature-card,
      .deal-card,
      .story-card,
      .stat,
      .hero__panel-list li,
      .bag-pill {
        forced-color-adjust: auto;
        box-shadow: none;
      }

      .brand-mark,
      .hero__art,
      .hero__art::before,
      .hero__art::after,
      .feature-card__shine {
        background: ButtonFace;
      }

      .btn,
      .card__button {
        border: 1px solid ButtonBorder;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <header class="site-header">
    <div class="shell site-header__inner">
      <a class="brand" href="#maincontent" aria-label="Luma Retail home">
        <span class="brand-mark" aria-hidden="true"></span>
        <span>Luma Retail</span>
      </a>

      <nav class="primary-nav" aria-label="Primary">
        <ul>
          <li><a href="#featured">Featured products</a></li>
          <li><a href="#deals">Deals</a></li>
          <li><a href="#editorial">Editorial</a></li>
          <li><a href="#footer">Service</a></li>
        </ul>
      </nav>

      <div class="utility">
        <span class="bag-pill" aria-label="Shopping bag">
          <span aria-hidden="true">Bag</span>
          <span class="bag-pill__count" data-cart-count>0</span>
        </span>
      </div>
    </div>
  </header>

  <main id="maincontent" tabindex="-1">
    <div class="shell">
      <section class="hero" aria-labelledby="hero-title">
        <div class="hero__content">
          <span class="eyebrow">New season / modern essentials</span>
          <h1 id="hero-title">Elevated retail for everyday style.</h1>
          <p class="lede">A clean, curated home page for a retail brand — designed to spotlight featured products, limited-time deals, and editorial stories in a polished, conversion-friendly layout.</p>
          <div class="hero__actions">
            <a class="btn btn--primary" href="#featured">Shop featured</a>
            <a class="btn btn--secondary" href="#deals">Browse deals</a>
          </div>
          <div class="hero__stats" aria-label="Store highlights">
            <div class="stat"><strong>Free shipping</strong><span>On orders over $75</span></div>
            <div class="stat"><strong>2-day delivery</strong><span>On best sellers</span></div>
            <div class="stat"><strong>Easy returns</strong><span>Within 30 days</span></div>
          </div>
        </div>

        <div class="hero__visual" aria-label="Seasonal collection preview">
          <div class="hero__art" aria-hidden="true"></div>
          <div class="hero__panel">
            <h2>Today’s edit</h2>
            <p>Neutral layers, soft tailoring, and home accents chosen to feel fresh, premium, and easy to shop.</p>
            <ul class="hero__panel-list">
              <li><span class="dot" aria-hidden="true"></span><span>Curated drops updated every morning</span></li>
              <li><span class="dot" aria-hidden="true"></span><span>Member-only pricing on select sets</span></li>
              <li><span class="dot" aria-hidden="true"></span><span>Editorial picks inspired by real outfits</span></li>
            </ul>
          </div>
        </div>
      </section>

      <section class="section" id="featured" aria-labelledby="featured-title">
        <div class="section__header">
          <div>
            <span class="eyebrow">Featured products</span>
            <h2 id="featured-title">Best-selling pieces with a refined finish.</h2>
          </div>
          <p>These product cards balance brand storytelling and commerce, making it easy to scan style, value, and availability at a glance.</p>
        </div>

        <div class="grid grid--products">
          <article class="feature-card" style="background: linear-gradient(180deg, #5d7b68 0, #dfe7da 100%);">
            <div class="feature-card__media">
              <span class="feature-card__tag">New</span>
              <span class="feature-card__shine" aria-hidden="true"></span>
            </div>
            <div class="feature-card__body">
              <h3 class="feature-card__title">Meridian Linen Overshirt</h3>
              <p>Breathable, structured, and easy to layer over weekend staples.</p>
              <div class="feature-card__meta">
                <span class="price">$98</span>
                <span>•</span>
                <span>In stock</span>
              </div>
              <button class="card__button" type="button" data-product="Meridian Linen Overshirt" data-price="$98">Add to bag</button>
            </div>
          </article>

          <article class="feature-card" style="background: linear-gradient(180deg, #8b5e3b 0, #f0d1b2 100%);">
            <div class="feature-card__media">
              <span class="feature-card__tag">Best seller</span>
              <span class="feature-card__shine" aria-hidden="true"></span>
            </div>
            <div class="feature-card__body">
              <h3 class="feature-card__title">Harbor Relaxed Trouser</h3>
              <p>Tailored drape with a soft hand-feel for work or travel.</p>
              <div class="feature-card__meta">
                <span class="price">$84</span>
                <span>•</span>
                <span>Limited colors</span>
              </div>
              <button class="card__button" type="button" data-product="Harbor Relaxed Trouser" data-price="$84">Add to bag</button>
            </div>
          </article>

          <article class="feature-card" style="background: linear-gradient(180deg, #4f5f8a 0, #d7def1 100%);">
            <div class="feature-card__media">
              <span class="feature-card__tag">Exclusive</span>
              <span class="feature-card__shine" aria-hidden="true"></span>
            </div>
            <div class="feature-card__body">
              <h3 class="feature-card__title">Studio Knit Crew</h3>
              <p>Lightweight knitwear with a crisp neckline and clean finish.</p>
              <div class="feature-card__meta">
                <span class="price">$72</span>
                <span>•</span>
                <span>Member price available</span>
              </div>
              <button class="card__button" type="button" data-product="Studio Knit Crew" data-price="$72">Add to bag</button>
            </div>
          </article>

          <article class="feature-card" style="background: linear-gradient(180deg, #7a3f52 0, #efd4db 100%);">
            <div class="feature-card__media">
              <span class="feature-card__tag">Trending</span>
              <span class="feature-card__shine" aria-hidden="true"></span>
            </div>
            <div class="feature-card__body">
              <h3 class="feature-card__title">Atlas Leather Sneaker</h3>
              <p>Minimal profile, cushioned support, and a premium matte finish.</p>
              <div class="feature-card__meta">
                <span class="price">$118</span>
                <span>•</span>
                <span>Low stock</span>
              </div>
              <button class="card__button" type="button" data-product="Atlas Leather Sneaker" data-price="$118">Add to bag</button>
            </div>
          </article>
        </div>
      </section>

      <section class="section" id="deals" aria-labelledby="deals-title">
        <div class="section__header">
          <div>
            <span class="eyebrow">Deals</span>
            <h2 id="deals-title">Limited-time offers that feel premium, not noisy.</h2>
          </div>
          <p>Promotions are presented as clear, scannable cards with strong hierarchy so the offer is easy to understand without visual clutter.</p>
        </div>

        <div class="grid grid--deals">
          <article class="deal-card">
            <div class="deal-card__body">
              <span class="deal-card__flag">48 hours left</span>
              <div class="deal-card__value">25% off bundles</div>
              <p>Build a full outfit with matching layers and save on the set.</p>
              <div class="deal-card__meta">
                <span>Selected apparel</span>
                <span>•</span>
                <span>Auto-applied at checkout</span>
              </div>
            </div>
          </article>

          <article class="deal-card">
            <div class="deal-card__body">
              <span class="deal-card__flag">Member exclusive</span>
              <div class="deal-card__value">Extra 15% on home</div>
              <p>Soft textures, tabletop pieces, and storage essentials are marked down for members.</p>
              <div class="deal-card__meta">
                <span>Home and decor</span>
                <span>•</span>
                <span>Ends Sunday</span>
              </div>
            </div>
          </article>

          <article class="deal-card">
            <div class="deal-card__body">
              <span class="deal-card__flag">New markdown</span>
              <div class="deal-card__value">Clearance picks from $24</div>
              <p>Last-chance colors and archive styles with a polished outlet feel.</p>
              <div class="deal-card__meta">
                <span>Final sizes</span>
                <span>•</span>
                <span>While supplies last</span>
              </div>
            </div>
          </article>
        </div>
      </section>

      <section class="section" id="editorial" aria-labelledby="editorial-title">
        <div class="section__header">
